23	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
24	// The target can be a remote name (e.g., "origin") or a URL for direct push.
25	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
26	// no remote tracking refs — git itself handles the no-op case.
27	// Does not check any settings — callers are responsible for gating.
28	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
29		repo, err := OpenRepository(ctx)
30		if err != nil {
31			return nil //nolint:nilerr // Hook must be silent on failure
32		}
33	
34		// Check if branch exists locally
35		branchRef := plumbing.NewBranchReferenceName(branchName)
36		localRef, err := repo.Reference(branchRef, true)
37		if err != nil {
38			// No branch, nothing to push
39			return nil //nolint:nilerr // Expected when no sessions exist yet
40		}
41	
42		// Only check remote tracking refs when target is a remote name (not a URL).
43		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
44		if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
45			return nil
46		}
47	
48		return doPushBranch(ctx, target, branchName)
49	}
