51	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
52	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
53	func hasUnpushedSessionsCommon(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
54		// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
55		remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
56		remoteRef, err := repo.Reference(remoteRefName, true)
57		if err != nil {
58			// Remote branch doesn't exist yet - we have content to push
59			return true
60		}
61	
62		// If local and remote point to same commit, nothing to sync
63		// This is the only case where we skip - any difference needs handling
64		return localHash != remoteRef.Hash()
65	}
