67	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
68	// The target can be a remote name or a URL.
69	func doPushBranch(ctx context.Context, target, branchName string) error {
70		displayTarget := target
71		if remote.IsURL(target) {
72			displayTarget = "checkpoint remote"
73		}
74	
75		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
76		stop := startProgressDots(os.Stderr)
77	
78		// Try pushing first
79		if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
80			finishPush(ctx, stop, result, target)
81			return nil
82		}
83		stop("")
84	
85		// Push failed - likely non-fast-forward. Try to fetch and rebase.
86		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
87		stop = startProgressDots(os.Stderr)
88	
89		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
90			stop("")
91			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
92			printCheckpointRemoteHint(target)
93			return nil // Don't fail the main push
94		}
95		stop(" done")
96	
97		// Try pushing again after rebase
98		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
99		stop = startProgressDots(os.Stderr)
100	
101		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
102			stop("")
103			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
104			printCheckpointRemoteHint(target)
105		} else {
106			finishPush(ctx, stop, result, target)
107		}
108	
109		return nil
110	}
