194	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
195	// at HEAD contains a valid checkpoint_remote configuration. This is the true
196	// discoverability check: entire.io reads from committed project settings, not from
197	// local overrides or uncommitted changes.
198	func isCheckpointRemoteCommitted(ctx context.Context) bool {
199		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
200		output, err := cmd.Output()
201		if err != nil {
202			return false // file doesn't exist at HEAD
203		}
204		// Parse the committed content and check for checkpoint_remote
205		committed, err := settings.LoadFromBytes(output)
206		if err != nil {
207			return false
208		}
209		return committed.GetCheckpointRemote() != nil
210	}
