467	// startProgressDots prints dots to w every second until the returned stop function
468	// is called. The stop function prints the given suffix and a newline.
469	func startProgressDots(w io.Writer) func(suffix string) {
470		done := make(chan struct{})
471		stopped := make(chan struct{})
472		go func() {
473			defer close(stopped)
474			ticker := time.NewTicker(time.Second)
475			defer ticker.Stop()
476			for {
477				select {
478				case <-done:
479					return
480				case <-ticker.C:
481					fmt.Fprint(w, ".")
482				}
483			}
484		}()
485		return func(suffix string) {
486			close(done)
487			<-stopped // Wait for goroutine to finish before writing suffix
488			fmt.Fprintln(w, suffix)
489		}
490	}
491	
492	// createMergeCommitCommon creates a merge commit with multiple parents.
493	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
494		authorName, authorEmail := GetGitAuthorFromRepo(repo)
495		now := time.Now()
496		sig := object.Signature{
497			Name:  authorName,
498			Email: authorEmail,
499			When:  now,
500		}
501	
502		commit := &object.Commit{
503			TreeHash:     treeHash,
504			ParentHashes: parents,
505			Author:       sig,
506			Committer:    sig,
507			Message:      message,
508		}
509	
510		checkpoint.SignCommitBestEffort(ctx, commit)
511	
512		obj := repo.Storer.NewEncodedObject()
513		if err := commit.Encode(obj); err != nil {
514			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
515		}
516	
517		hash, err := repo.Storer.SetEncodedObject(obj)
518		if err != nil {
519			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
520		}
521	
522		return hash, nil
523	}
