27	// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
28	// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
29	// no "has unpushed" optimization — we always attempt the push and let git handle
30	// the no-op case.
31	func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
32		repo, err := OpenRepository(ctx)
33		if err != nil {
34			return nil //nolint:nilerr // Hook must be silent on failure
35		}
36	
37		if _, err := repo.Reference(refName, true); err != nil {
38			return nil //nolint:nilerr // Ref doesn't exist locally, nothing to push
39		}
40	
41		return doPushRef(ctx, target, refName)
42	}
