44	// tryPushRef attempts to push a custom ref using an explicit refspec.
45	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) (pushResult, error) {
46		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
47		defer cancel()
48	
49		refSpec := fmt.Sprintf("%s:%s", refName, refName)
50		result, err := remote.Push(ctx, target, refSpec)
51		outputStr := result.Output
52		if err != nil {
53			if strings.Contains(outputStr, "non-fast-forward") ||
54				strings.Contains(outputStr, "rejected") {
55				return pushResult{}, errors.New("non-fast-forward")
56			}
57			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
58		}
59	
60		return parsePushResult(outputStr), nil
61	}
