63	// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
64	func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
65		displayTarget := target
66		if remote.IsURL(target) {
67			displayTarget = "checkpoint remote"
68		}
69	
70		shortRef := shortRefName(refName)
71		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
72		stop := startProgressDots(os.Stderr)
73	
74		if result, err := tryPushRef(ctx, target, refName); err == nil {
75			finishPush(ctx, stop, result, target)
76			return nil
77		}
78		stop("")
79	
80		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
81		stop = startProgressDots(os.Stderr)
82	
83		if err := fetchAndMergeRef(ctx, target, refName); err != nil {
84			stop("")
85			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
86			printCheckpointRemoteHint(target)
87			return nil
88		}
89		stop(" done")
90	
91		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
92		stop = startProgressDots(os.Stderr)
93	
94		if result, err := tryPushRef(ctx, target, refName); err != nil {
95			stop("")
96			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
97			printCheckpointRemoteHint(target)
98		} else {
99			finishPush(ctx, stop, result, target)
100		}
101	
102		return nil
103	}
