105	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
106	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
107	//
108	// For /full/current: if the remote has archived generations not present locally,
109	// another machine rotated. In that case, local data is merged into the latest
110	// archived generation instead of into /full/current (see handleRotationConflict).
111	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
112		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
113		defer cancel()
114	
115		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
116		if err != nil {
117			return fmt.Errorf("resolve fetch target: %w", err)
118		}
119	
120		// Fetch to a temp ref
121		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
122		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
123		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
124	
125		if output, err := remote.Fetch(ctx, remote.FetchOptions{
126			Remote:   fetchTarget,
127			RefSpecs: []string{refSpec},
128			NoTags:   true,
129		}); err != nil {
130			return fmt.Errorf("fetch failed: %s", output)
131		}
132	
133		repo, err := OpenRepository(ctx)
134		if err != nil {
135			return fmt.Errorf("failed to open repository: %w", err)
136		}
137		defer func() {
138			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
139		}()
140	
141		// Check for rotation conflict on /full/current
142		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
143			remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
144			if detectErr == nil && len(remoteOnlyArchives) > 0 {
145				return handleRotationConflict(ctx, target, fetchTarget, repo, refName, tmpRefName, remoteOnlyArchives)
146			}
147		}
148	
149		// Standard tree merge (no rotation detected)
150		localRef, err := repo.Reference(refName, true)
151		if err != nil {
152			return fmt.Errorf("failed to get local ref: %w", err)
153		}
154		localCommit, err := repo.CommitObject(localRef.Hash())
155		if err != nil {
156			return fmt.Errorf("failed to get local commit: %w", err)
157		}
158		localTree, err := localCommit.Tree()
159		if err != nil {
160			return fmt.Errorf("failed to get local tree: %w", err)
161		}
162	
163		remoteRef, err := repo.Reference(tmpRefName, true)
164		if err != nil {
165			return fmt.Errorf("failed to get remote ref: %w", err)
166		}
167		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
168		if err != nil {
169			return fmt.Errorf("failed to get remote commit: %w", err)
170		}
171		remoteTree, err := remoteCommit.Tree()
172		if err != nil {
173			return fmt.Errorf("failed to get remote tree: %w", err)
174		}
175	
176		entries := make(map[string]object.TreeEntry)
177		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
178			return fmt.Errorf("failed to flatten local tree: %w", err)
179		}
180		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
181			return fmt.Errorf("failed to flatten remote tree: %w", err)
182		}
183	
184		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
185		if err != nil {
186			return fmt.Errorf("failed to build merged tree: %w", err)
187		}
188	
189		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
190			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
191			"Merge remote "+shortRefName(refName))
192		if err != nil {
193			return fmt.Errorf("failed to create merge commit: %w", err)
194		}
195	
196		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
197		if err := repo.Storer.SetReference(newRef); err != nil {
198			return fmt.Errorf("failed to update ref: %w", err)
199		}
200	
201		return nil
202	}
