241	// handleRotationConflict handles the case where remote /full/current was rotated.
242	// Merges local /full/current into the latest remote archived generation to avoid
243	// duplicating checkpoint data, then adopts remote's /full/current as local.
244	func handleRotationConflict(ctx context.Context, target, fetchTarget string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
245		// Use the latest remote-only archive
246		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
247		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
248	
249		// Fetch the latest archived generation
250		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
251		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
252		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
253			Remote:   fetchTarget,
254			RefSpecs: []string{archiveRefSpec},
255			NoTags:   true,
256		}); fetchErr != nil {
257			return fmt.Errorf("fetch archived generation failed: %s", output)
258		}
259		defer func() {
260			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
261		}()
262	
263		// Get archived generation state
264		archiveRef, err := repo.Reference(archiveTmpRef, true)
265		if err != nil {
266			return fmt.Errorf("failed to get archived ref: %w", err)
267		}
268		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
269		if err != nil {
270			return fmt.Errorf("failed to get archive commit: %w", err)
271		}
272		archiveTree, err := archiveCommit.Tree()
273		if err != nil {
274			return fmt.Errorf("failed to get archive tree: %w", err)
275		}
276	
277		// Get local /full/current state
278		localRef, err := repo.Reference(refName, true)
279		if err != nil {
280			return fmt.Errorf("failed to get local ref: %w", err)
281		}
282		localCommit, err := repo.CommitObject(localRef.Hash())
283		if err != nil {
284			return fmt.Errorf("failed to get local commit: %w", err)
285		}
286		localTree, err := localCommit.Tree()
287		if err != nil {
288			return fmt.Errorf("failed to get local tree: %w", err)
289		}
290	
291		// Tree-merge local /full/current into archived generation.
292		// Git content-addressing deduplicates shared shard paths automatically.
293		entries := make(map[string]object.TreeEntry)
294		if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
295			return fmt.Errorf("failed to flatten archive tree: %w", err)
296		}
297		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
298			return fmt.Errorf("failed to flatten local tree: %w", err)
299		}
300	
301		// Update generation.json timestamps if present in the merged tree.
302		// Use the local /full/current HEAD commit time as the newest checkpoint time
303		// (more accurate than time.Now() for cleanup scheduling).
304		if genEntry, exists := entries[paths.GenerationFileName]; exists {
305			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
306				entries[paths.GenerationFileName] = updatedEntry
307			} else {
308				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
309					slog.String("error", updateErr.Error()),
310				)
311			}
312		}
313	
314		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
315		if err != nil {
316			return fmt.Errorf("failed to build merged tree: %w", err)
317		}
318	
319		// Create commit parented on archive's commit (fast-forward)
320		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
321			[]plumbing.Hash{archiveRef.Hash()},
322			"Merge local checkpoints into archived generation")
323		if err != nil {
324			return fmt.Errorf("failed to create merge commit: %w", err)
325		}
326	
327		// Update local archived ref and push it
328		newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
329		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
330			return fmt.Errorf("failed to update archive ref: %w", err)
331		}
332	
333		if _, pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
334			return fmt.Errorf("failed to push updated archive: %w", pushErr)
335		}
336	
337		// Adopt remote's /full/current as local
338		remoteRef, err := repo.Reference(tmpRefName, true)
339		if err != nil {
340			return fmt.Errorf("failed to get fetched /full/current: %w", err)
341		}
342		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
343		if err := repo.Storer.SetReference(adoptedRef); err != nil {
344			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
345		}
346	
347		return nil
348	}
