350	// updateGenerationTimestamps reads generation.json from a blob, updates
351	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
352	// an updated tree entry. Uses the local commit timestamp rather than
353	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
354	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
355		blob, err := repo.BlobObject(genBlobHash)
356		if err != nil {
357			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
358		}
359		reader, err := blob.Reader()
360		if err != nil {
361			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
362		}
363		defer reader.Close()
364	
365		data, err := io.ReadAll(reader)
366		if err != nil {
367			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
368		}
369	
370		var gen checkpoint.GenerationMetadata
371		if err := json.Unmarshal(data, &gen); err != nil {
372			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
373		}
374	
375		if newestFromLocal.After(gen.NewestCheckpointAt) {
376			gen.NewestCheckpointAt = newestFromLocal
377		}
378	
379		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
380		if err != nil {
381			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
382		}
383	
384		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
385		if err != nil {
386			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
387		}
388	
389		return object.TreeEntry{
390			Name: paths.GenerationFileName,
391			Mode: filemode.Regular,
392			Hash: newBlobHash,
393		}, nil
394	}
