396	// pushV2Refs pushes v2 checkpoint refs to the target.
397	// Pushes /main, /full/current, and the latest archived generation (if any).
398	// Older archived generations are immutable and were pushed when created.
399	func pushV2Refs(ctx context.Context, target string) {
400		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
401		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
402	
403		// Push only the latest archived generation (most likely to be newly created)
404		repo, err := OpenRepository(ctx)
405		if err != nil {
406			return
407		}
408		v2URL, err := remote.FetchURL(ctx)
409		if err != nil {
410			logging.Debug(ctx, "push-v2: using origin for archived generation fetch remote",
411				slog.String("error", err.Error()),
412			)
413		}
414		store := checkpoint.NewV2GitStore(repo, v2URL)
415		archived, err := store.ListArchivedGenerations()
416		if err != nil || len(archived) == 0 {
417			return
418		}
419		latest := archived[len(archived)-1]
420		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
421	}
