423	// shortRefName returns a human-readable short form of a ref name for log output.
424	// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
425	func shortRefName(refName plumbing.ReferenceName) string {
426		const prefix = "refs/entire/checkpoints/"
427		s := string(refName)
428		if strings.HasPrefix(s, prefix) {
429			return s[len(prefix):]
430		}
431		return s
432	}
