// TestIsProtectedRefRejection covers the indicators we use to distinguish a
// GitHub branch-protection / ruleset rejection (GH013) from a generic
// non-fast-forward rejection. Protected-ref rejections cannot be resolved by
// fetch+rebase, so classification must not lump them in with NFF.
func TestIsProtectedRefRejection(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name   string
		output string
		want   bool
	}{
		{
			name: "GH013 ruleset rejection",
			output: "remote: error: GH013: Repository rule violations found for refs/heads/entire/checkpoints/v1.\n" +
				"remote: error: Cannot update this protected ref.\n" +
				" ! [remote rejected]       entire/checkpoints/v1 -> entire/checkpoints/v1 (push declined due to repository rule violations)\n" +
				"error: failed to push some refs to 'github.com:org/repo.git'",
			want: true,
		},
		{
			name:   "Cannot update this protected ref phrase alone",
			output: "remote: error: Cannot update this protected ref.",
			want:   true,
		},
		{
			name:   "legacy protected branch hook declined",
			output: " ! [remote rejected] main -> main (protected branch hook declined)",
			want:   true,
		},
		{
			name:   "plain non-fast-forward is not a protected-ref rejection",
			output: " ! [rejected] entire/checkpoints/v1 -> entire/checkpoints/v1 (non-fast-forward)",
			want:   false,
		},
		{
			name:   "empty output",
			output: "",
			want:   false,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, tc.want, isProtectedRefRejection(tc.output))
		})
	}
}

